// gta6-meme-x-01 (replacement candidate) — "Post a GTA 6 meme on X".
//
// The meme: a LEONIDA AIR boarding pass. The passenger — one patient
// gamer — booked a flight from Real Life to Vice City on 17 Sep 2013.
// The flight has been delayed 4,811 days. It is finally NOW BOARDING,
// and the fare was paid by the passenger's AI agent out of its make.fun
// bounty winnings.
//
// What this program does, in order:
//   1. Copies POST.json from the repository root to the output directory,
//      where the make.fun gate reads it.
//   2. Renders the meme itself — a 1024x1024 PNG drawn entirely with this
//      file's own rasterizer, embedded Liberation Sans outlines and PNG encoder (Node
//      standard library only: node:fs, node:path, node:zlib). No network,
//      no wall clock, no randomness beyond a fixed-seed generator, so two
//      runs write byte-identical output.
//
// Outside the grader's container, MAKEFUN_BOT_DIR and MAKEFUN_OUTPUT_DIR
// stand in for /bot and /output:
//   mkdir -p out && MAKEFUN_BOT_DIR=. MAKEFUN_OUTPUT_DIR=out node main.ts

import { copyFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { deflateSync } from 'node:zlib';

const BOT_DIR = process.env.MAKEFUN_BOT_DIR ?? '/bot';
const OUTPUT_DIR = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';

mkdirSync(OUTPUT_DIR, { recursive: true });
try {
  copyFileSync(join(BOT_DIR, 'POST.json'), join(OUTPUT_DIR, 'POST.json'));
} catch (err) {
  console.error(`POST.json could not be copied from ${BOT_DIR}: ${(err as Error).message}`);
  process.exit(1);
}

// ---------------------------------------------------------------------------
// Frame buffer. The pass is painted at 2x (2048x2048) and box-downsampled
// to 1024x1024 at the end, which anti-aliases every edge for free. All
// drawing functions below take design coordinates on a 1024x1024 canvas.
// ---------------------------------------------------------------------------

type RGB = [number, number, number];

const SS = 2; // supersampling factor
const DW = 1024; // design width/height
const PW = DW * SS; // pixel width/height
const img = new Uint8ClampedArray(PW * PW * 3);

function setPx(px: number, py: number, c: RGB): void {
  if (px < 0 || py < 0 || px >= PW || py >= PW) return;
  const i = (py * PW + px) * 3;
  img[i] = c[0];
  img[i + 1] = c[1];
  img[i + 2] = c[2];
}

function blendPx(px: number, py: number, c: RGB, a: number): void {
  if (px < 0 || py < 0 || px >= PW || py >= PW || a <= 0) return;
  const i = (py * PW + px) * 3;
  img[i] = img[i] * (1 - a) + c[0] * a;
  img[i + 1] = img[i + 1] * (1 - a) + c[1] * a;
  img[i + 2] = img[i + 2] * (1 - a) + c[2] * a;
}

// Paint every pixel of a design-space bounding box whose centre satisfies
// fn; fn returns a colour, or null to leave the pixel alone.
function paint(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  fn: (x: number, y: number) => RGB | null,
): void {
  const px0 = Math.max(0, Math.floor(x0 * SS));
  const py0 = Math.max(0, Math.floor(y0 * SS));
  const px1 = Math.min(PW - 1, Math.ceil(x1 * SS));
  const py1 = Math.min(PW - 1, Math.ceil(y1 * SS));
  for (let py = py0; py <= py1; py++) {
    const y = (py + 0.5) / SS;
    for (let px = px0; px <= px1; px++) {
      const x = (px + 0.5) / SS;
      const c = fn(x, y);
      if (c !== null) setPx(px, py, c);
    }
  }
}

function paintBlend(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  fn: (x: number, y: number) => { c: RGB; a: number } | null,
): void {
  const px0 = Math.max(0, Math.floor(x0 * SS));
  const py0 = Math.max(0, Math.floor(y0 * SS));
  const px1 = Math.min(PW - 1, Math.ceil(x1 * SS));
  const py1 = Math.min(PW - 1, Math.ceil(y1 * SS));
  for (let py = py0; py <= py1; py++) {
    const y = (py + 0.5) / SS;
    for (let px = px0; px <= px1; px++) {
      const x = (px + 0.5) / SS;
      const r = fn(x, y);
      if (r !== null) blendPx(px, py, r.c, r.a);
    }
  }
}

function fillRect(x: number, y: number, w: number, h: number, c: RGB): void {
  paint(x, y, x + w, y + h, (px, py) => (px >= x && px < x + w && py >= y && py < y + h ? c : null));
}

function fillCircle(cx: number, cy: number, r: number, c: RGB): void {
  paint(cx - r, cy - r, cx + r, cy + r, (x, y) => {
    const dx = x - cx;
    const dy = y - cy;
    return dx * dx + dy * dy <= r * r ? c : null;
  });
}

function fillCircleBlend(cx: number, cy: number, r: number, c: RGB, a: number): void {
  paintBlend(cx - r, cy - r, cx + r, cy + r, (x, y) => {
    const dx = x - cx;
    const dy = y - cy;
    return dx * dx + dy * dy <= r * r ? { c, a } : null;
  });
}

function ring(cx: number, cy: number, r: number, halfWidth: number, c: RGB): void {
  paint(cx - r - halfWidth, cy - r - halfWidth, cx + r + halfWidth, cy + r + halfWidth, (x, y) => {
    const d = Math.hypot(x - cx, y - cy);
    return Math.abs(d - r) <= halfWidth ? c : null;
  });
}

function fillPoly(pts: [number, number][], c: RGB): void {
  let x0 = Infinity;
  let y0 = Infinity;
  let x1 = -Infinity;
  let y1 = -Infinity;
  for (const [x, y] of pts) {
    x0 = Math.min(x0, x);
    y0 = Math.min(y0, y);
    x1 = Math.max(x1, x);
    y1 = Math.max(y1, y);
  }
  paint(x0, y0, x1, y1, (x, y) => {
    let inside = false;
    for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
      const [xi, yi] = pts[i];
      const [xj, yj] = pts[j];
      if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
    }
    return inside ? c : null;
  });
}

// One stroked segment with round caps. alpha < 1 blends over the canvas.
function strokeSeg(
  xa: number,
  ya: number,
  xb: number,
  yb: number,
  halfWidth: number,
  c: RGB,
  alpha = 1,
): void {
  const pad = halfWidth + 1;
  const test = (x: number, y: number): number => {
    const dx = xb - xa;
    const dy = yb - ya;
    const len2 = dx * dx + dy * dy;
    let t = len2 === 0 ? 0 : ((x - xa) * dx + (y - ya) * dy) / len2;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(x - (xa + t * dx), y - (ya + t * dy));
  };
  if (alpha >= 1) {
    paint(
      Math.min(xa, xb) - pad,
      Math.min(ya, yb) - pad,
      Math.max(xa, xb) + pad,
      Math.max(ya, yb) + pad,
      (x, y) => (test(x, y) <= halfWidth ? c : null),
    );
  } else {
    paintBlend(
      Math.min(xa, xb) - pad,
      Math.min(ya, yb) - pad,
      Math.max(xa, xb) + pad,
      Math.max(ya, yb) + pad,
      (x, y) => (test(x, y) <= halfWidth ? { c, a: alpha } : null),
    );
  }
}

// Stroke a whole polyline (consecutive points joined, round joins come
// free because every segment has round caps).
function strokePath(pts: [number, number][], halfWidth: number, c: RGB, alpha = 1): void {
  for (let i = 1; i < pts.length; i++) {
    strokeSeg(pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1], halfWidth, c, alpha);
  }
}

// Vertical gradient over a rectangle; stops are [at, colour] pairs.
function vGrad(x: number, y: number, w: number, h: number, stops: [number, RGB][]): void {
  paint(x, y, x + w, y + h, (px, py) => {
    if (px < x || px >= x + w || py < y || py >= y + h) return null;
    return gradAt(stops, (py - y) / h);
  });
}

function gradAt(stops: [number, RGB][], t: number): RGB {
  if (t <= stops[0][0]) return stops[0][1];
  for (let i = 1; i < stops.length; i++) {
    if (t <= stops[i][0]) {
      const [t0, c0] = stops[i - 1];
      const [t1, c1] = stops[i];
      const f = (t - t0) / (t1 - t0);
      return [
        Math.round(c0[0] + (c1[0] - c0[0]) * f),
        Math.round(c0[1] + (c1[1] - c0[1]) * f),
        Math.round(c0[2] + (c1[2] - c0[2]) * f),
      ];
    }
  }
  return stops[stops.length - 1][1];
}

function roundedRect(x: number, y: number, w: number, h: number, r: number, c: RGB): void {
  paint(x, y, x + w, y + h, (px, py) => {
    const qx = Math.max(x + r - px, px - (x + w - r), 0);
    const qy = Math.max(y + r - py, py - (y + h - r), 0);
    const inRect = px >= x && px < x + w && py >= y && py < y + h;
    return inRect && qx * qx + qy * qy <= r * r + r ? c : null;
  });
}

// Perimeter points of a rounded rectangle centred at (cx, cy), optionally
// rotated by rotDeg (counterclockwise on screen). Used for box outlines
// and the rubber stamp.
function roundedRectPts(
  cx: number,
  cy: number,
  w: number,
  h: number,
  r: number,
  rotDeg = 0,
): [number, number][] {
  const pts: [number, number][] = [];
  const hw = w / 2;
  const hh = h / 2;
  const corners: [number, number, number][] = [
    [hw - r, -hh + r, 0],
    [-hw + r, -hh + r, 90],
    [-hw + r, hh - r, 180],
    [hw - r, hh - r, 270],
  ];
  for (const [ccx, ccy, start] of corners) {
    for (let i = 0; i <= 6; i++) {
      const a = ((start + (i * 90) / 6) * Math.PI) / 180;
      pts.push([ccx + r * Math.cos(a), ccy - r * Math.sin(a)]);
    }
  }
  const rot = (rotDeg * Math.PI) / 180;
  const cos = Math.cos(rot);
  const sin = Math.sin(rot);
  return pts.map(([lx, ly]): [number, number] => [
    cx + lx * cos + ly * sin,
    cy - lx * sin + ly * cos,
  ]);
}

function roundedRectStroke(
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
  c: RGB,
  halfWidth: number,
): void {
  // Signed-distance stroke of the rounded-rect perimeter: perfectly even
  // line weight all the way round, no polyline joins to wobble.
  const cx = x + w / 2;
  const cy = y + h / 2;
  paint(x - halfWidth - 2, y - halfWidth - 2, x + w + halfWidth + 2, y + h + halfWidth + 2, (px, py) => {
    const qx = Math.abs(px - cx) - (w / 2 - r);
    const qy = Math.abs(py - cy) - (h / 2 - r);
    const d = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - r;
    return Math.abs(d) <= halfWidth ? c : null;
  });
}

// Fixed-seed PRNG (mulberry32): the barcode, the QR pattern and other
// "random" details are identical on every run.
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ---------------------------------------------------------------------------
// PNG encoder. Downsamples the 2x buffer to 1024x1024, then writes a PNG
// with per-row adaptive filtering (minimum sum of absolute differences
// over None/Sub/Up/Average/Paeth) and zlib deflate.
// ---------------------------------------------------------------------------

const CRC_TABLE = ((): Int32Array => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

function crc32(buf: Buffer): number {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function pngChunk(type: string, data: Buffer): Buffer {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([len, body, crc]);
}

function paeth(a: number, b: number, c: number): number {
  const p = a + b - c;
  const pa = Math.abs(p - a);
  const pb = Math.abs(p - b);
  const pc = Math.abs(p - c);
  if (pa <= pb && pa <= pc) return a;
  if (pb <= pc) return b;
  return c;
}

function encodePng(): Buffer {
  const W = DW;
  const raw = Buffer.alloc(W * W * 3);
  for (let y = 0; y < W; y++) {
    for (let x = 0; x < W; x++) {
      let r = 0;
      let g = 0;
      let b = 0;
      for (let dy = 0; dy < SS; dy++) {
        for (let dx = 0; dx < SS; dx++) {
          const i = ((y * SS + dy) * PW + (x * SS + dx)) * 3;
          r += img[i];
          g += img[i + 1];
          b += img[i + 2];
        }
      }
      const o = (y * W + x) * 3;
      raw[o] = Math.round(r / (SS * SS));
      raw[o + 1] = Math.round(g / (SS * SS));
      raw[o + 2] = Math.round(b / (SS * SS));
    }
  }

  const bpp = 3;
  const stride = W * bpp;
  const filtered = Buffer.alloc(W * (stride + 1));
  let prev: Buffer | null = null;
  for (let y = 0; y < W; y++) {
    const row = raw.subarray(y * stride, (y + 1) * stride);
    let bestType = 0;
    let bestScore = Infinity;
    let bestRow: Buffer | null = null;
    for (let type = 0; type <= 4; type++) {
      const out = Buffer.alloc(stride);
      let score = 0;
      for (let i = 0; i < stride; i++) {
        const a = i >= bpp ? row[i - bpp] : 0;
        const b = prev ? prev[i] : 0;
        const c = prev && i >= bpp ? prev[i - bpp] : 0;
        let pred = 0;
        if (type === 1) pred = a;
        else if (type === 2) pred = b;
        else if (type === 3) pred = (a + b) >> 1;
        else if (type === 4) pred = paeth(a, b, c);
        const v = (row[i] - pred) & 0xff;
        out[i] = v;
        score += v < 128 ? v : 256 - v;
      }
      if (score < bestScore) {
        bestScore = score;
        bestType = type;
        bestRow = out;
      }
    }
    const off = y * (stride + 1);
    filtered[off] = bestType;
    (bestRow as Buffer).copy(filtered, off + 1);
    prev = row;
  }

  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(W, 0);
  ihdr.writeUInt32BE(W, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type: truecolour RGB
  ihdr[10] = 0; // compression
  ihdr[11] = 0; // filter
  ihdr[12] = 0; // interlace

  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    pngChunk('IHDR', ihdr),
    pngChunk('IDAT', deflateSync(filtered, { level: 9 })),
    pngChunk('IEND', Buffer.alloc(0)),
  ]);
}

// ---------------------------------------------------------------------------
// Type. Real font outlines: glyph data below was generated at build
// time from Liberation Sans (Regular + Bold) — cmap/glyf quadratic
// outlines and hmtx advances, parsed from the TTFs and embedded here
// as M/L/Q/Z op strings in font units, so this file never reads a
// system font at runtime. Liberation Sans is licensed under the SIL
// Open Font License 1.1. Text is filled with the nonzero winding
// rule on the supersampled framebuffer: each glyph outline is
// flattened (fixed quadratic subdivision) and scanline-filled.
// `size` is the cap height in design px; scale = size / capHeight.
// ---------------------------------------------------------------------------

